     setProvider(shared.provider);\n          showError(null);\n          setResetMsg(t(\"settings.resetDone\"));\n          if (resetTimer.current) clearTimeout(resetTimer.current);\n          resetTimer.current = setTimeout(() => setResetMsg(null), 3000);\n        };\n        const showError = msg => {\n          if (errorTimer.current) {\n            clearTimeout(errorTimer.current);\n            errorTimer.current = null;\n          }\n          setError(msg);\n          if (msg) {\n            errorTimer.current = setTimeout(() => {\n              setError(null);\n              errorTimer.current = null;\n            }, 5000);\n          }\n        };\n        const onPreview = () => {\n          const target = plainText(preview);\n          if (!target) {\n            showError(t(\"preview.emptyError\"));\n            return;\n          }\n          if (isPreviewPlaying) {\n            stopSpeaking();\n            setPlayingText(null);\n            return;\n          }\n          showError(null);\n          setPlayingText(target);\n          // speakText already reports every real failure through onError with\n          // the raw message (or voice.removed); the returned promise only\n          // resets the preview state here (avoiding double-display).\n          speakText(target, \"manual\", msg =>\n            showError(t(\"synthFail\") + msg),\n          ).then(r => {\n            if (r && !r.ok) setPlayingText(null);\n          });\n        };\n        const voiceOptions = VOICES\n          .filter(v => !shared.removedVoices.has(v[0]))\n          .map(v =>\n          react.createElement(\"option\", { key: v[0], value: v[0] }, v[1]),\n        );\n        const [provider, setProvider] = react.useState(shared.provider);\n        const [, setRvcTick] = react.useState(0);\n        const changeProvider = e => {\n          shared.provider = e.target.value;\n          saveSettings();\n          setProvider(e.target.value);\n        };\n        const setRvc = (key, value) => {\n          shared.rvc[key] = value;\n          saveSettings();\n          if (HOST_RVC_KEYS.indexOf(key) >= 0) {\n            const patch = {};\n            patch[key] = value;\n            pushHostRvc(patch);\n          }\n          setRvcTick(n => n + 1);\n        };\n        // ---- 本地 Index-TTS2（参考音频音色）----\n        const [, setIndexTick] = react.useState(0);\n        const setIndex = (key, value) => {\n          shared.index[key] = value;\n          saveSettings();\n          if (HOST_INDEX_KEYS.indexOf(key) >= 0) {\n            const patch = {};\n            patch[key] = value;\n            pushHostIndex(patch);\n          }\n          setIndexTick(n => n + 1);\n        };\n        const [indexVoices, setIndexVoices] = react.useState({ loading: false, error: null, list: [] });\n        const refreshIndexVoices = async () => {\n          setIndexVoices({ loading: true, error: null, list: [] });\n          try {\n            const r = await fetch(\n              \"/dsh-tts-api/index-voices?baseUrl=\" + encodeURIComponent(shared.index.baseUrl),\n            );\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            const list = Array.isArray(data.voices) ? data.voices : [];\n            setIndexVoices({ loading: false, error: null, list });\n            // auto-select the first voice when nothing is chosen yet\n            if (!shared.index.voice && list.length) setIndex(\"voice\", list[0]);\n            else setIndexTick(n => n + 1);\n          } catch (e) {\n            setIndexVoices({\n              loading: false,\n              error: t(\"index.voices.fail\") + String((e && e.message) || e),\n              list: [],\n            });\n          }\n        };\n        const [indexUpload, setIndexUpload] = react.useState(null); // { busy, error, ok }\n        const uploadIndexVoice = async file => {\n          if (!file) return;\n          setIndexUpload({ busy: true, error: null, ok: null });\n          try {\n            const buf = await file.arrayBuffer();\n            let binary = \"\";\n            const bytes = new Uint8Array(buf);\n            const CHUNK = 32768;\n            for (let i = 0; i < bytes.length; i += CHUNK) {\n              binary += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));\n            }\n            const r = await fetch(\"/dsh-tts-api/index-upload\", {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({\n                baseUrl: shared.index.baseUrl,\n                filename: file.name,\n                audioBase64: btoa(binary),\n              }),\n            });\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            const name = data.filename || file.name;\n            setIndexUpload({ busy: false, error: null, ok: t(\"index.upload.ok\") + name });\n            await refreshIndexVoices();\n            if (name) setIndex(\"voice\", name);\n          } catch (e) {\n            setIndexUpload({ busy: false, error: t(\"index.upload.fail\") + String((e && e.message) || e), ok: null });\n          }\n        };\n        // entering the Index-TTS2 provider auto-loads the voice list once\n        react.useEffect(() => {\n          if (provider === \"index-tts2\" && !indexVoices.loading && !indexVoices.list.length && !indexVoices.error) {\n            refreshIndexVoices();\n          }\n        }, [provider]);\n        // ---- 本地 CosyVoice（提示音频克隆）----\n        const [, setCosyTick] = react.useState(0);\n        const setCosy = (key, value) => {\n          shared.cosy[key] = value;\n          saveSettings();\n          if (HOST_COSY_KEYS.indexOf(key) >= 0) {\n            const patch = {};\n            patch[key] = value;\n            pushHostCosy(patch);\n          }\n          setCosyTick(n => n + 1);\n        };\n        const [cosyVoices, setCosyVoices] = react.useState({ loading: false, error: null, list: [] });\n        const refreshCosyVoices = async () => {\n          setCosyVoices({ loading: true, error: null, list: [] });\n          try {\n            const r = await fetch(\n              \"/dsh-tts-api/cosy-voices?baseUrl=\" + encodeURIComponent(shared.cosy.baseUrl),\n            );\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            const list = Array.isArray(data.voices) ? data.voices : [];\n            setCosyVoices({ loading: false, error: null, list });\n            // auto-select the first voice when nothing is chosen yet\n            if (!shared.cosy.voice && list.length) setCosy(\"voice\", list[0]);\n            else setCosyTick(n => n + 1);\n          } catch (e) {\n            setCosyVoices({\n              loading: false,\n              error: t(\"cosy.voices.fail\") + String((e && e.message) || e),\n              list: [],\n            });\n          }\n        };\n        const [cosyUpload, setCosyUpload] = react.useState(null); // { busy, error, ok }\n        const uploadCosyVoice = async file => {\n          if (!file) return;\n          setCosyUpload({ busy: true, error: null, ok: null });\n          try {\n            const buf = await file.arrayBuffer();\n            let binary = \"\";\n            const bytes = new Uint8Array(buf);\n            const CHUNK = 32768;\n            for (let i = 0; i < bytes.length; i += CHUNK) {\n              binary += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));\n            }\n            const r = await fetch(\"/dsh-tts-api/cosy-upload\", {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({\n                baseUrl: shared.cosy.baseUrl,\n                filename: file.name,\n                audioBase64: btoa(binary),\n              }),\n            });\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            const name = data.filename || file.name;\n            setCosyUpload({ busy: false, error: null, ok: t(\"cosy.upload.ok\") + name });\n            await refreshCosyVoices();\n            if (name) setCosy(\"voice\", name);\n          } catch (e) {\n            setCosyUpload({ busy: false, error: t(\"cosy.upload.fail\") + String((e && e.message) || e), ok: null });\n          }\n        };\n        // entering the CosyVoice provider auto-loads the voice list once\n        react.useEffect(() => {\n          if (provider === \"cosyvoice\" && !cosyVoices.loading && !cosyVoices.list.length && !cosyVoices.error) {\n            refreshCosyVoices();\n          }\n        }, [provider]);\n        // ---- Google Cloud TTS（付费在线音色）----\n        const [, setCloudTick] = react.useState(0);\n        const setCloud = (key, value) => {\n          shared.cloud[key] = value;\n          saveSettings();\n          setCloudTick(n => n + 1);\n        };\n        // Key input is write-only local state (never saved, never from Host).\n        const [cloudKey, setCloudKey] = react.useState(\"\");\n        const [cloudProject, setCloudProject] = react.useState(null); // null = not loaded yet\n        const [cloudSave, setCloudSave] = react.useState(null); // { busy, ok, error }\n        const [cloudTest, setCloudTest] = react.useState(null); // { busy, ok, error }\n        const [cloudUsage, setCloudUsage] = react.useState(null); // { loading, error, month, tiers } | null\n        // entering the Cloud provider pulls key-status + usage once\n        react.useEffect(() => {\n          if (provider === \"google-cloud-tts\") {\n            refreshCloudConfig();\n            refreshCloudUsage();\n          }\n        }, [provider]);\n        // keep the Project ID input in sync with the Host value once loaded\n        react.useEffect(() => {\n          if (cloudProject === null && shared.cloudHost && typeof shared.cloudHost.projectId === \"string\") {\n            setCloudProject(shared.cloudHost.projectId);\n          }\n        });\n        const refreshCloudUsage = async () => {\n          setCloudUsage({ loading: true, error: null, month: \"\", tiers: null });\n          try {\n            const r = await fetch(\"/dsh-tts-api/cloud-usage\");\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            setCloudUsage({ loading: false, error: null, month: data.month || \"\", tiers: data.tiers || null });\n          } catch (e) {\n            setCloudUsage({ loading: false, error: String((e && e.message) || e), month: \"\", tiers: null });\n          }\n        };\n        const saveCloudConfig = async () => {\n          const patch = {};\n          if (cloudKey.trim() !== \"\") patch.apiKey = cloudKey.trim();\n          if (cloudProject !== null) patch.projectId = cloudProject.trim();\n          if (!patch.apiKey && cloudProject === null) return;\n          setCloudSave({ busy: true, ok: null, error: null });\n          try {\n            const r = await fetch(\"/dsh-tts-api/cloud-config-save\", {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ cloud: patch }),\n            });\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            setCloudKey(\"\");\n            refreshCloudConfig();\n            refreshCloudUsage();\n            setCloudSave({ busy: false, ok: t(\"cloud.saved\"), error: null });\n          } catch (e) {\n            setCloudSave({ busy: false, ok: null, error: String((e && e.message) || e) });\n          }\n        };\n        const clearCloudKey = async () => {\n          if (!window.confirm(t(\"cloud.confirmClear.lead\") + t(\"cloud.confirmClear.tail\"))) return;\n          setCloudSave({ busy: true, ok: null, error: null });\n          try {\n            const r = await fetch(\"/dsh-tts-api/cloud-config-save\", {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ cloud: { apiKey: \"\" } }),\n            });\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            setCloudKey(\"\");\n            refreshCloudConfig();\n            setCloudSave({ busy: false, ok: t(\"cloud.cleared\"), error: null });\n          } catch (e) {\n            setCloudSave({ busy: false, ok: null, error: String((e && e.message) || e) });\n          }\n        };\n        const testCloudKey = async () => {\n          setCloudTest({ busy: true, ok: null, error: null });\n          try {\n            const r = await fetch(\"/dsh-tts-api/cloud-test\", {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ voice: shared.cloud.voice || \"cmn-CN-Wavenet-A\" }),\n            });\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            refreshCloudUsage();\n            setCloudTest({ busy: false, ok: t(\"cloud.test.ok\"), error: null });\n          } catch (e) {\n            setCloudTest({ busy: false, ok: null, error: String((e && e.message) || e) });\n          }\n        };\n        // ---- 文件选择器（RVC 服务文件发现）----\n        const [picker, setPicker] = react.useState(null);\n        // Esc closes the file picker; click on the transparent overlay also closes it\n        react.useEffect(() => {\n          const onKey = e => {\n            if (e.key === \"Escape\") setPicker(null);\n          };\n          window.addEventListener(\"keydown\", onKey);\n          return () => window.removeEventListener(\"keydown\", onKey);\n        }, []);\n        const openPicker = async kind => {\n          setPicker({ kind, files: [], loading: true, error: null });\n          try {\n            const r = await fetch(\n              \"/dsh-tts-api/rvc-files?baseUrl=\" +\n                encodeURIComponent(shared.rvc.baseUrl) +\n                \"&kind=\" +\n                kind,\n            );\n            const data = await r.json().catch(() => null);\n            if (!r.ok || !data || data.error) {\n              throw new Error(hostErrText(data) || (\"HTTP \" + r.status));\n            }\n            setPicker({ kind, files: data.files || [], loading: false, error: null });\n          } catch (e) {\n            setPicker({\n              kind,\n              files: [],\n              loading: false,\n              error: t(\"fileListFail\") + String((e && e.message) || e),\n            });\n          }\n        };\n        const pickFile = (kind, f) => {\n          setRvc(kind === \"pth\" ? \"model\" : \"index\", f.path);\n          setPicker(null);\n        };\n        // ---- 音色包（注册表 + 下载安装）----\n        const PKG_SETTINGS_KEY = \"dsh-tts-pack-settings\"; // { registry, proxy }\n        const PKG_ACTIVE_KEY = \"dsh-tts-pack-active\";      // { key, packId }\n        const [registryUrl, setRegistryUrl] = react.useState(\"\");\n        const [packProxy, setPackProxy] = react.useState(\"\");\n        const [packs, setPacks] = react.useState(null); // { loading, error, list }\n        const [installed, setInstalled] = react.useState({});\n        const [installing, setInstalling] = react.useState(null);\n        const [packNote, setPackNote] = react.useState(null);\n        const [packIdx, setPackIdx] = react.useState({}); // packId -> selected index variant id\n        const [installProg, setInstallProg] = react.useState(null); // { packId, pct, phase, speed }\n        const [packsDir, setPacksDir] = react.useState(null);\n        const savePackSettings = () => {\n          try {\n            localStorage.setItem(\n              PKG_SETTINGS_KEY,\n              JSON.stringify({ registry: registryUrl.trim(), proxy: packProxy.trim() }),\n            );\n          } catch (e) { /* non-fatal */ }\n        };\n        const refreshInstalled = async () => {\n          try {\n            const r = await fetch(\"/dsh-tts-api/rvc-packs-installed\");\n            const d = await r.json().catch(() => null);\n            if (d && d.installed) setInstalled(d.installed);\n            if (d && d.packsDir) setPacksDir(d.packsDir);\n          } catch (e) { /* non-fatal */ }\n        };\n        // restore persisted settings + re-attach to an in-flight download\n        react.useEffect(() => {\n          refreshInstalled();\n          try {\n            const s = JSON.parse(localStorage.getItem(PKG_SETTINGS_KEY) || \"null\");\n            if (s) {\n              if (s.registry) setRegistryUrl(s.registry);\n              if (s.proxy) setPackProxy(s.proxy);\n            }\n          } catch (e) { /* non-fatal */ }\n          try {\n            const a = JSON.parse(localStorage.getItem(PKG_ACTIVE_KEY) || \"null\");\n            if (a && a.key && a.packId) restoreActiveInstall(a.key, a.packId);\n            else localStorage.removeItem(PKG_ACTIVE_KEY);\n          } catch (e) { /* non-fatal */ }\n        }, []);\n        // re-attach to a download started before the panel was closed\n        const restoreActiveInstall = (key, packId) => {\n          let waitingCount = 0;\n          const poll = async () => {\n            for (let i = 0; i < 120; i++) {\n              await new Promise(res => setTimeout(res, 500));\n              try {\n                const pr = await fetch(\"/dsh-tts-api/rvc-pack-progress?key=\" + encodeURIComponent(key));\n                const d = await pr.json().catch(() => null);\n                if (d && d.finished) {\n                  setInstalling(null);\n                  setInstallProg(null);\n                  localStorage.removeItem(PKG_ACTIVE_KEY);\n                  refreshInstalled();\n                  return;\n                }\n                if (d && d.waiting !== true && d.total) {\n                  waitingCount = 0;\n                  setInstalling(packId);\n                  setInstallProg({\n                    packId,\n                    pct: Math.min(100, Math.round((d.done / d.total) * 100)),\n                    phase: (d.phaseKey && t(\"host.phase.\" + d.phaseKey) !== \"host.phase.\" + d.phaseKey)\n                      ? t(\"host.phase.\" + d.phaseKey)\n                      : (d.phase === t(\"tab.index\") ? t(\"tab.index\") : t(\"tab.model\")),\n                    speed: d.speed || 0,\n                  });\n                  continue;\n                }\n                // no entry yet — either still preparing or already gone\n                waitingCount++;\n                if (waitingCount > 4) {\n                  // give up: entry expired without a finish flag\n                  localStorage.removeItem(PKG_ACTIVE_KEY);\n                  setInstalling(null);\n                  setInstallProg(null);\n                  refreshInstalled();\n                  return;\n                }\n                setInstalling(packId);\n                setInstallProg({ packId, pct: 0, phase: t(\"busy.preparing\"), speed: 0 });\n              } catch (e) { /* transient */ }\n      